#ifndef _WIN32
#include <signal.h>
#endif
static int gorget_generic_compare(const void* a, const void* b) { return memcmp(a, b, sizeof(int64_t)); }
static int gorget_int_compare(const void* a, const void* b) { int64_t va = *(const int64_t*)a, vb = *(const int64_t*)b; return (va > vb) - (va < vb); }
static int gorget_float_compare(const void* a, const void* b) { double da = *(const double*)a, db = *(const double*)b; return (da > db) - (da < db); }
static int gorget_str_compare(const void* a, const void* b) { Str sa = *(const Str*)a, sb = *(const Str*)b; size_t la = sa.len, lb = sb.len; size_t ml = la < lb ? la : lb; int r = ml > 0 ? memcmp(sa.data, sb.data, ml) : 0; if (r) return r; return (la > lb) - (la < lb); }
static inline int64_t int64_t__one(void) { return 1; }
static inline int64_t int__one(void) { return 1; }
static inline double double__one(void) { return 1.0; }
static inline double float__one(void) { return 1.0; }

